-- Phase 5 migration for SATS
CREATE TABLE IF NOT EXISTS quotation_items (id INTEGER PRIMARY KEY AUTOINCREMENT, quotation_id INTEGER NOT NULL, description TEXT NOT NULL, qty REAL NOT NULL DEFAULT 1, unit TEXT NOT NULL DEFAULT 'LS', rate REAL NOT NULL DEFAULT 0, amount REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS invoice_items (id INTEGER PRIMARY KEY AUTOINCREMENT, invoice_id INTEGER NOT NULL, description TEXT NOT NULL, qty REAL NOT NULL DEFAULT 1, unit TEXT NOT NULL DEFAULT 'LS', rate REAL NOT NULL DEFAULT 0, amount REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS supplier_payments (id INTEGER PRIMARY KEY AUTOINCREMENT, supplier_id INTEGER, amount REAL NOT NULL DEFAULT 0, date TEXT, reference TEXT);
CREATE TABLE IF NOT EXISTS bank_accounts (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, account_type TEXT NOT NULL DEFAULT 'Bank', opening_balance REAL NOT NULL DEFAULT 0, current_balance REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS cash_transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, account_id INTEGER, type TEXT NOT NULL, amount REAL NOT NULL DEFAULT 0, date TEXT, category TEXT, reference TEXT, project_id INTEGER, notes TEXT);